function canonicalFromFields(fields){var out={};fields.forEach(function(f){out[f.id]=String(f.answer);});return out;}function expectedText(fields){return fields.map(function(f){var shown=f.answer;if(f.options){var o=f.options.find(function(x){return x.value===String(f.answer);});if(o)shown=o.label;}return(f.label?f.label+": ":"")+shown;}).join("; ");}
function generateQuestion(familyId,level,seed){var family=familyById(familyId),data=scenario(family.id,Math.max(1,Math.min(5,Number(level)||1)),new Rng(seed)),fields=data.fields;if(TEXT.localeCode!=="en"){data.title=translateGenerated(data.title);data.rows=data.rows.map(translateGenerated);data.note=translateGenerated(data.note);data.explanation=translateGenerated(data.explanation);fields.forEach(function(f){f.label=translateGenerated(f.label);if(f.options)f.options.forEach(function(o){o.label=translateGenerated(o.label);});});}return{familyId:family.id,categoryId:family.categoryId,level:Math.max(1,Math.min(5,Number(level)||1)),prompt:{title:data.title,rows:data.rows,note:data.note},fields:fields,canonicalAnswer:canonicalFromFields(fields),expectedText:expectedText(fields),explanation:data.explanation,structuralSignature:family.id+":"+data.signature,metadata:{model:MODEL_ID,semanticSignature:data.signature}};}
function normalizeSequence(value){return String(value).trim().toUpperCase().replace(/(?:→|->|;|\s+)/g,",").split(",").filter(Boolean).join(",");}function normalizeInteger(value){try{return BigInt(String(value).trim().replace(/_/g,"")).toString();}catch(e){return null;}}function normalizeFraction(value){var m=String(value).trim().match(/^(-?\d+)\s*\/\s*(-?\d+)$/);if(!m||BigInt(m[2])===0n)return null;return fraction(BigInt(m[1]),BigInt(m[2]));}
function normalized(value,kind){if(kind==="integer")return normalizeInteger(value);if(kind==="fraction")return normalizeFraction(value);if(kind==="sequence"||kind==="intseq"||kind==="truthseq")return normalizeSequence(value);return String(value).trim();}
function checkQuestion(answers,q){var ok=q.fields.every(function(f){return normalized(answers[f.id],f.kind)===normalized(f.answer,f.kind);});return{correct:ok,expectedText:q.expectedText};}

