function runSelfTests(){var failures=[];function assert(name,condition){if(!condition)failures.push(name);}assert("six categories",CATEGORIES.length===6);assert("33 families",FAMILIES.length===33);assert("unique family ids",new Set(FAMILIES.map(function(f){return f.id;})).size===33);assert("unique keypad ids",new Set(KEY_IDS).size===KEY_IDS.length);assert("truth keys available",allowed("truthseq").every(function(id){return KEY_IDS.includes(id);}));if(TEXT.localeCode==="sv"){assert("Swedish categories",CATEGORIES.every(function(c){return TEXT.categories&&TEXT.categories[c.id];}));assert("Swedish families",FAMILIES.every(function(f){return TEXT.families&&TEXT.families[f.id]&&TEXT.familyRules&&TEXT.familyRules[f.id];}));}assert("growth antisymmetry",GROWTH.every(function(a){return GROWTH.every(function(b){return compareGrowth(a.id,b.id)===-compareGrowth(b.id,a.id);});}));for(var aa=1;aa<=4;aa+=1)for(var bb=2;bb<=3;bb+=1)for(var kk=1;kk<=5;kk+=1)assert("recurrence integer "+aa+bb+kk,recurrenceValue(aa,bb,kk,1,1)>0n);for(var mask=0;mask<16;mask+=1){var len=4,bits=mask.toString(2).padStart(len,"0");assert("bit enumeration "+mask,countBitStrings(len,function(s){return s===bits;})===1);}var dg={v:["A","B","C","D"],e:[["A","B",4],["A","C",1],["C","B",2],["B","D",1],["C","D",5]],d:true},dr=dijkstra(dg.v,dg.e,dg.d,"A");assert("Dijkstra landmark",dr.dist.D===4&&shortestPath(dr,"A","D").join("")==="ACBD");assert("BFS landmark",bfs(["A","B","C"],[["A","B"],["B","C"]],false,"A").order.join("")==="ABC");assert("topological landmark",topological(["A","B","C"],[["A","C"],["B","C"]]).join("")==="ABC");assert("logic implication",logicEval(["imp","p","q"],{p:true,q:false})===false);var englishLeak=/\b(?:which|what|how|give|choose|run|find|count|evaluate|complete|trace|final|answer|value|distance|path|order|true|false|displayed|growth|class|models|strict|exact|expected|worst|case|structure|tree|table|graph|directed|undirected|neighbor|neighbors|vertex|vertices|edge|edges|smallest|first|each|every|from|with|without|before|after|only|same|different|the|this|these|and|or|not|is|are|gives|contains|possible|probability|outcomes|items|objects|categories|all|one|two|at least|at most|none|remaining|unreachable|settled|predecessor|canonical|normalize|multiply|add|select|compare)\b/i;FAMILIES.forEach(function(f,fi){LEVELS.forEach(function(level){var signatures=new Set();for(var sample=0;sample<50;sample+=1){try{var q=generateQuestion(f.id,level,((fi+1)*1000000+level*1000+sample+1)>>>0);assert("canonical "+f.id+":"+level+":"+sample,checkQuestion(q.canonicalAnswer,q).correct);assert("metadata "+f.id+":"+level+":"+sample,q.metadata.model===MODEL_ID&&q.structuralSignature.indexOf(f.id+":")===0);if(TEXT.localeCode==="sv"){var localized=[q.prompt.title].concat(q.prompt.rows,[q.prompt.note,q.explanation],q.fields.map(function(x){return x.label;}),q.fields.reduce(function(a,x){return a.concat((x.options||[]).map(function(o){return o.label;}));},[])).join(" ");assert("Swedish generated "+f.id+":"+level+":"+sample,!englishLeak.test(localized));}signatures.add(q.structuralSignature);}catch(e){failures.push("generator "+f.id+":"+level+":"+sample+" "+e.message);}}assert("variation "+f.id+":"+level,signatures.size>=2);});});if(failures.length){console.error("Computer-science self-tests failed",failures.slice(0,100),"total",failures.length);return{ok:false,failures:failures.slice(0,100)};}console.info("Computer-science self-tests passed: 33 families, exact symbolic/trace/graph/logic/counting oracles, 8,250 generated instances"+(TEXT.localeCode==="sv"?", Swedish generated-text coverage":""));return{ok:true,failures:[]};}
